{
  "claims": [
    {
      "quote": "In the fall of 2003, Elizabeth Holmes, a 19-year-old sophomore at Stanford, plopped herself down in the office of her chemical engineering professor, Channing Robertson, and said, “Let’s start a company.”",
      "kind": "specific",
      "why": "This claim mentions Elizabeth Holmes, Channing Robertson, Stanford, and the year 2003."
    },
    {
      "quote": "Now she’s 30, and her private, Palo Alto-based corporation, called Theranos–the name is an amalgam of the words “therapy” and “diagnosis”–has 500 employees and has raised more than $400 million from equity sales to investors who have effectively valued the company at more than $9 billion.",
      "kind": "specific",
      "why": "This claim contains specific numbers like 30, 500 employees, $400 million, and $9 billion."
    },
    {
      "quote": "Theranos today is a potentially highly disruptive upstart in America’s $73 billion diagnostic-lab industry, which performs nearly 10 billion tests a year and is estimated to provide the basis for about 70% of doctors’ medical decisions.",
      "kind": "specific",
      "why": "This checkable claim mentions the $73 billion industry size and 10 billion tests."
    },
    {
      "quote": "Medicare and Medicaid each pay roughly $10 billion annually on reimbursements for these tests.",
      "kind": "specific",
      "why": "This claim specifies Medicare, Medicaid, and $10 billion in annual reimbursements."
    },
    {
      "quote": "It currently offers more than 200–and is ramping up to offer more than 1,000–of the most commonly ordered blood diagnostic tests, all without the need for a syringe.",
      "kind": "specific",
      "why": "This claim relies on the numbers 200 and 1,000 for blood diagnostic tests."
    },
    {
      "quote": "Production in Theranos’s 262,000-square-foot manufacturing facility in Newark, Calif.",
      "kind": "specific",
      "why": "This mentions Newark, Calif., and the 262,000-square-foot size of the manufacturing facility."
    },
    {
      "quote": "Its phlebotomists currently take physician-ordered blood draws (and saliva, urine, feces, and other samples) at collection centers the company operates at its headquarters in Palo Alto and at 21 Walgreens–one in Palo Alto and the rest in Phoenix.",
      "kind": "specific",
      "why": "This includes locations like Palo Alto and Phoenix, alongside 21 Walgreens."
    },
    {
      "quote": "At least as significant, three hospital groups are now working closely with Theranos with the aim of deploying its lab services–UCSF Medical Center in San Francisco, Dignity Health’s 21-state hospital group, and Intermountain Healthcare’s 22-hospital system in Utah and Idaho.",
      "kind": "specific",
      "why": "This checkable claim names specific medical centers and regional hospital groups."
    }
  ]
}

